content:
@layer components {
  .shelf-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--shelf-space-md);
  }

  @media (min-width: 768px) {
    .shelf-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }
}

@layer components {
  .shelf-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--shelf-space-md);
  }

  @media (width >= 768px) {
    .shelf-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
  }

  @media (max-height: 600px) {
    .drawer {
      max-block-size: 50vh;
    }
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
  }

  @media (height >= 600px) {
    .drawer {
      max-block-size: 70vh;
    }
  }
}

@layer tokens {
  :root {
    --shelf-bgColor-default: hsl(30 15% 97%);
    --shelf-fgColor-default: hsl(16 12% 10%);
  }
}

@media (min-width: 768px) {
  :root {
    --shelf-space-lg: 2rem;
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
  }

  @media (max-width: 1024px) {
    .book-card {
      padding: var(--shelf-space-sm);
    }
  }
}

@layer components {
  .shelf-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--shelf-space-md);
  }

  @media (width >= 768px) {
    .shelf-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (width >= 1024px) {
    .shelf-grid {
      grid-template-columns: repeat(3, 1fr);
    }
  }
}
